SELECT jsonb_build_object(
 'rawSHA256',$1::text,
 'newFunctions',(SELECT jsonb_agg(jsonb_build_object('signature','public.'||p.proname||'('||replace(oidvectortypes(p.proargtypes),', ',',')||')','definition',pg_get_functiondef(p.oid),'source_md5',md5(p.prosrc),'portable',jsonb_build_object('owner',pg_get_userbyid(p.proowner),'language',l.lanname,'kind',p.prokind,'security_definer',p.prosecdef,'leakproof',p.proleakproof,'strict',p.proisstrict,'set_returning',p.proretset,'volatility',p.provolatile,'parallel',p.proparallel,'cost',p.procost,'rows',p.prorows,'config',p.proconfig,'arg_names',p.proargnames,'identity_args',pg_get_function_identity_arguments(p.oid),'full_args',pg_get_function_arguments(p.oid),'result',pg_get_function_result(p.oid),'acl',p.proacl::text))ORDER BY p.proname)FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public'AND p.proname=ANY(ARRAY['uc_dsr_working_2026','uc_dsr_add_days','uc_dsr_can_manage','uc_dsr_fence','uc_dsr_authority_fence','uc_dsr_create','uc_dsr_list','uc_dsr_apply'])),
 'oldTwo',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'source_md5',md5(p.prosrc),'metadata',to_jsonb(p)-'prosrc')ORDER BY p.proname)FROM pg_proc p WHERE p.oid IN('public.set_dsr_due_date()'::regprocedure,'public.get_documents_kpi(uuid)'::regprocedure)),
 'newHistoryClass',(SELECT to_jsonb(c)FROM pg_class c WHERE c.oid='public.data_subject_request_deadline_events'::regclass),
 'newHistoryColumns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text)ORDER BY a.attnum)FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.data_subject_request_deadline_events'::regclass AND a.attnum>0 AND NOT a.attisdropped),
 'newHistoryConstraints',(SELECT jsonb_agg(jsonb_build_object('name',c.conname,'definition',pg_get_constraintdef(c.oid,true),'type',c.contype,'deferrable',c.condeferrable,'deferred',c.condeferred,'validated',c.convalidated,'update',c.confupdtype,'delete',c.confdeltype,'match',c.confmatchtype)ORDER BY c.conname)FROM pg_constraint c WHERE c.conrelid='public.data_subject_request_deadline_events'::regclass),
 'newDSRConstraints',(SELECT jsonb_agg(jsonb_build_object('name',c.conname,'definition',pg_get_constraintdef(c.oid,true),'type',c.contype,'deferrable',c.condeferrable,'deferred',c.condeferred,'validated',c.convalidated)ORDER BY c.conname)FROM pg_constraint c WHERE c.conrelid='public.data_subject_requests'::regclass AND c.conname IN('data_subject_requests_request_type_check','data_subject_requests_deadline_revision_check','data_subject_requests_deadline_details_check')),
 'oldDSRAttributesAfter',(SELECT jsonb_agg(to_jsonb(a)ORDER BY a.attnum)FROM pg_attribute a WHERE a.attrelid='public.data_subject_requests'::regclass),
 'parentFKTriggers',(SELECT jsonb_agg(jsonb_build_object('parent_schema',pn.nspname,'parent_table',pr.relname,'child_schema',cn.nspname,'child_table',cr.relname,'constraint_name',c.conname,'constraint_definition',pg_get_constraintdef(c.oid,true),'function_identity',fnn.nspname||'.'||quote_ident(fn.proname)||'('||pg_get_function_identity_arguments(fn.oid)||')','tgtype',t.tgtype,'tgenabled',t.tgenabled,'tgisinternal',t.tgisinternal,'tgdeferrable',t.tgdeferrable,'tginitdeferred',t.tginitdeferred,'tgnargs',t.tgnargs,'tgargs_hex',encode(t.tgargs,'hex'),'tgattr',t.tgattr::text,'confupdtype',c.confupdtype,'confdeltype',c.confdeltype,'confmatchtype',c.confmatchtype,'convalidated',c.convalidated)ORDER BY pn.nspname,pr.relname,c.conname,t.tgtype)FROM pg_trigger t JOIN pg_constraint c ON c.oid=t.tgconstraint JOIN pg_class pr ON pr.oid=t.tgrelid JOIN pg_namespace pn ON pn.oid=pr.relnamespace JOIN pg_class cr ON cr.oid=c.conrelid JOIN pg_namespace cn ON cn.oid=cr.relnamespace JOIN pg_proc fn ON fn.oid=t.tgfoid JOIN pg_namespace fnn ON fnn.oid=fn.pronamespace WHERE t.tgisinternal AND c.contype='f'AND c.conrelid='public.data_subject_request_deadline_events'::regclass AND c.confrelid=t.tgrelid),
 'historyRows',(SELECT count(*)FROM data_subject_request_deadline_events))d;
